draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var th = p.angle * Math.PI / 180;
var F = p.force, d = 6.0;
var Wk = F * d * Math.cos(th);

function arw(x1, y1, x2, y2, col, lw) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = lw;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), hl = 8;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - hl * Math.cos(a - 0.4), y2 - hl * Math.sin(a - 0.4));
  ctx.lineTo(x2 - hl * Math.cos(a + 0.4), y2 - hl * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

var gy = H * 0.70;
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(W * 0.04, gy); ctx.lineTo(W * 0.96, gy); ctx.stroke();

var bw = W * 0.11, bh = H * 0.15;
var bx = W * 0.20;
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.5;
ctx.strokeRect(bx, gy - bh, bw, bh);
ctx.fillStyle = C.ink;
ctx.fillText("sled", bx + bw * 0.18, gy - bh * 0.35);

var ox = bx + bw, oy = gy - bh;
var scale = W * 0.0042;
var ex = ox + F * scale * Math.cos(th);
var ey = oy - F * scale * Math.sin(th);
arw(ox, oy, ex, ey, C.accent, 2);
ctx.fillStyle = C.accent;
ctx.fillText("F = " + F.toFixed(0) + " N", ex + 6, ey - 2);

var cx = ox + F * scale * Math.cos(th);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(ex, ey); ctx.lineTo(cx, oy); ctx.stroke();
ctx.setLineDash([]);
arw(ox, oy, cx, oy, C.figure, 2);
ctx.fillStyle = C.figure;
ctx.fillText("F cos" + "θ = " + (F * Math.cos(th)).toFixed(1) + " N", ox + 4, oy - 8);

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(ox, oy, 26, -th, 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("θ = " + p.angle.toFixed(0) + "°", ox + 30, oy - 26 * Math.sin(th / 2) - 4);

var ay = gy + H * 0.14;
arw(bx, ay, bx + W * 0.45, ay, C.rule, 1.5);
ctx.fillStyle = C.ink;
ctx.fillText("d = 6.0 m", bx + W * 0.16, ay + 15);

ctx.fillStyle = C.faint;
ctx.fillText("only the shaded-out horizontal part travels with the sled", W * 0.04, H * 0.13);

out.note = "W = F d cosθ = " + F.toFixed(0) + " × 6.0 × " + Math.cos(th).toFixed(3) + " = " + Wk.toFixed(1) + " J";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var F0 = p.f0, k = p.slope, xe = p.xend;

var xMax = 6.0;
var fvals = [];
var i, x, f;
var fHi = 1, fLo = -1;
for (i = 0; i <= 120; i++) {
  x = xMax * i / 120;
  f = F0 + k * x;
  if (f > fHi) fHi = f;
  if (f < fLo) fLo = f;
}
fHi = fHi * 1.2; fLo = fLo * 1.2;

var padL = W * 0.11, padR = W * 0.05, padT = H * 0.12, padB = H * 0.22;
var sx = (W - padL - padR) / xMax;
var sy = (H - padT - padB) / (fHi - fLo);
function X(v) { return padL + v * sx; }
function Y(v) { return H - padB - (v - fLo) * sy; }

ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(xMax), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(0), Y(fLo)); ctx.lineTo(X(0), Y(fHi)); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("F (N)", X(0) - 4, Y(fHi) + 10);
ctx.fillText("x (m)", X(xMax) - 34, Y(0) + 16);
for (i = 1; i <= 6; i++) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(X(i), Y(0) - 3); ctx.lineTo(X(i), Y(0) + 3); ctx.stroke();
  ctx.fillStyle = C.faint;
  ctx.fillText("" + i, X(i) - 3, Y(0) + 16);
}

var steps = 160;
var dx = xe / steps;
var Wpos = 0, Wneg = 0;
for (i = 0; i < steps; i++) {
  x = dx * (i + 0.5);
  f = F0 + k * x;
  if (f >= 0) { Wpos += f * dx; } else { Wneg += f * dx; }
}
var Wtot = Wpos + Wneg;

for (i = 0; i < steps; i++) {
  x = dx * i;
  f = F0 + k * (x + dx / 2);
  ctx.fillStyle = f >= 0 ? C.accent : C.figure;
  ctx.globalAlpha = 0.25;
  var yTop = Y(Math.max(f, 0)), yBot = Y(Math.min(f, 0));
  ctx.fillRect(X(x), yTop, Math.max(sx * dx + 0.6, 0.6), Math.max(yBot - yTop, 0));
  ctx.globalAlpha = 1;
}

ctx.strokeStyle = C.ink; ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 120; i++) {
  x = xMax * i / 120;
  f = F0 + k * x;
  if (i === 0) { ctx.moveTo(X(x), Y(f)); } else { ctx.lineTo(X(x), Y(f)); }
}
ctx.stroke();

ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(X(xe), Y(fLo)); ctx.lineTo(X(xe), Y(fHi)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("finish x = " + xe.toFixed(1) + " m", X(xe) + 5, Y(fHi) + 12);

ctx.fillStyle = C.ink;
ctx.fillText("F = " + F0.toFixed(1) + (k >= 0 ? " + " : " − ") + Math.abs(k).toFixed(1) + " x", padL, H * 0.09);

ctx.fillStyle = C.faint;
ctx.fillText("shaded area = work done", padL, H - 4);

out.note = "positive area " + Wpos.toFixed(2) + " J, negative area " + Wneg.toFixed(2) + " J, total work " + Wtot.toFixed(2) + " J";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var g = 9.8;
var th = p.angle * Math.PI / 180;
var v0 = p.v0, mu = p.mu, m = 2.0;
var aUp = g * (Math.sin(th) + mu * Math.cos(th));
var dStop = v0 * v0 / (2 * aUp);
var tUp = v0 / aUp;
var slides = Math.tan(th) > mu;
var aDown = g * (Math.sin(th) - mu * Math.cos(th));
var tDown = slides ? Math.sqrt(2 * dStop / aDown) : 1.2;
var period = tUp + tDown + 0.8;
var tc = t % period;

var s, v;
if (tc < tUp) {
  s = v0 * tc - 0.5 * aUp * tc * tc;
  v = v0 - aUp * tc;
} else if (tc < tUp + tDown && slides) {
  var td = tc - tUp;
  s = dStop - 0.5 * aDown * td * td;
  v = -aDown * td;
} else if (tc < tUp + tDown) {
  s = dStop; v = 0;
} else {
  s = slides ? 0 : dStop; v = 0;
}
if (s < 0) { s = 0; }

var padL = W * 0.09, padB = H * 0.16;
var avail = Math.min((W - padL - W * 0.12) / Math.cos(th), (H - padB - H * 0.22) / Math.sin(th));
var mScale = avail / Math.max(dStop * 1.15, 0.6);
var Lpx = Math.max(dStop, 0.4) * 1.15 * mScale;

var bx0 = padL, by0 = H - padB;
var tx = bx0 + Lpx * Math.cos(th), ty = by0 - Lpx * Math.sin(th);

ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(bx0, by0); ctx.lineTo(bx0 + Lpx * Math.cos(th), by0); ctx.stroke();
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(bx0, by0); ctx.lineTo(tx, ty); ctx.stroke();
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(bx0, by0, 24, -th, 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + "°", bx0 + 28, by0 - 6);

var stx = bx0 + dStop * mScale * Math.cos(th), sty = by0 - dStop * mScale * Math.sin(th);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(stx - 12 * Math.sin(th), sty - 12 * Math.cos(th));
ctx.lineTo(stx + 16 * Math.sin(th), sty + 16 * Math.cos(th));
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("stops at " + dStop.toFixed(2) + " m", stx + 6, sty - 10);

var px = bx0 + s * mScale * Math.cos(th), py = by0 - s * mScale * Math.sin(th);
var bs = Math.max(H * 0.09, 12);
ctx.save();
ctx.translate(px, py);
ctx.rotate(-th);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.strokeRect(-bs / 2, -bs, bs, bs);
ctx.restore();

var K = 0.5 * m * v * v;
ctx.fillStyle = C.figure;
ctx.fillText("v = " + Math.abs(v).toFixed(2) + " m/s", W * 0.55, H * 0.20);
ctx.fillText("K = " + K.toFixed(1) + " J", W * 0.55, H * 0.20 + 16);
ctx.fillStyle = C.faint;
ctx.fillText("m = 2.0 kg", W * 0.55, H * 0.20 + 32);

out.note = "gravity takes " + (m * g * Math.sin(th) * dStop).toFixed(1) + " J, friction takes " + (mu * m * g * Math.cos(th) * dStop).toFixed(1) + " J, start K = " + (0.5 * m * v0 * v0).toFixed(1) + " J, stopping distance " + dStop.toFixed(2) + " m";
